#!/bin/sh
# Historical commands, in execution order. Not a test runner.
# Before pass-1, the source was TwitchControl.precedence-error.tla.txt.
# Before all subsequent calls, the source was the final TwitchControl.tla.
XDG_RUNTIME_DIR="/run/user/$(id -u)" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$(id -u)/bus" systemd-run --user --scope --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA=/tmp/agents/irl-shield/m3-model/java TLA2TOOLS=OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' OWNER_HOME/.agents/skills/statechart/scripts/statechart /tmp/agents/irl-shield/m3-model/TwitchControl.tla --config /tmp/agents/irl-shield/m3-model/TwitchControl.cfg --view /tmp/agents/irl-shield/m3-model/view.mjs --out /tmp/agents/irl-shield/m3-model/pass-1 > /tmp/agents/irl-shield/m3-model/pass-1.command.log 2>&1
XDG_RUNTIME_DIR="/run/user/$(id -u)" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$(id -u)/bus" systemd-run --user --scope --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA=/tmp/agents/irl-shield/m3-model/java TLA2TOOLS=OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' OWNER_HOME/.agents/skills/statechart/scripts/statechart /tmp/agents/irl-shield/m3-model/TwitchControl.tla --config /tmp/agents/irl-shield/m3-model/TwitchControl.cfg --view /tmp/agents/irl-shield/m3-model/view.mjs --out /tmp/agents/irl-shield/m3-model/pass-2 > /tmp/agents/irl-shield/m3-model/pass-2.command.log 2>&1
XDG_RUNTIME_DIR="/run/user/$(id -u)" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$(id -u)/bus" systemd-run --user --scope --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA=/tmp/agents/irl-shield/m3-model/java TLA2TOOLS=OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' OWNER_HOME/.agents/skills/statechart/scripts/statechart /tmp/agents/irl-shield/m3-model/TwitchControl.tla --config /tmp/agents/irl-shield/m3-model/authority.cfg --view /tmp/agents/irl-shield/m3-model/view.mjs --out /tmp/agents/irl-shield/m3-model/authority > /tmp/agents/irl-shield/m3-model/authority.command.log 2>&1
XDG_RUNTIME_DIR="/run/user/$(id -u)" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$(id -u)/bus" systemd-run --user --scope --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA=/tmp/agents/irl-shield/m3-model/java TLA2TOOLS=OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' OWNER_HOME/.agents/skills/statechart/scripts/statechart /tmp/agents/irl-shield/m3-model/TwitchControl.tla --config /tmp/agents/irl-shield/m3-model/replay.cfg --view /tmp/agents/irl-shield/m3-model/view.mjs --out /tmp/agents/irl-shield/m3-model/replay > /tmp/agents/irl-shield/m3-model/replay.command.log 2>&1
XDG_RUNTIME_DIR="/run/user/$(id -u)" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$(id -u)/bus" systemd-run --user --scope --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA=/tmp/agents/irl-shield/m3-model/java TLA2TOOLS=OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' OWNER_HOME/.agents/skills/statechart/scripts/statechart /tmp/agents/irl-shield/m3-model/TwitchControl.tla --config /tmp/agents/irl-shield/m3-model/coverage.cfg --view /tmp/agents/irl-shield/m3-model/view.mjs --out /tmp/agents/irl-shield/m3-model/coverage > /tmp/agents/irl-shield/m3-model/coverage.command.log 2>&1
XDG_RUNTIME_DIR="/run/user/$(id -u)" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$(id -u)/bus" systemd-run --user --scope --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env JAVA=/tmp/agents/irl-shield/m3-model/java TLA2TOOLS=OWNER_HOME/.local/share/mise/installs/http-tla2tools/1.7.4/tla2tools.jar JAVA_TOOL_OPTIONS='-XX:ActiveProcessorCount=2 -Xmx1g -XX:+UseParallelGC' OWNER_HOME/.agents/skills/statechart/scripts/statechart /tmp/agents/irl-shield/m3-model/TwitchControl.tla --config /tmp/agents/irl-shield/m3-model/TwitchControl.cfg --view /tmp/agents/irl-shield/m3-model/view.mjs --out /tmp/agents/irl-shield/m3-model/restored > /tmp/agents/irl-shield/m3-model/restored.command.log 2>&1
# First Python call used replay_counterexamples.first.py.txt; the log was then
# preserved as python-replay.first.log before correcting the cache assertion.
XDG_RUNTIME_DIR="/run/user/$(id -u)" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$(id -u)/bus" systemd-run --user --scope --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env PYTHONDONTWRITEBYTECODE=1 python3 /tmp/agents/irl-shield/m3-model/replay_counterexamples.py --source WORKTREE_t3-3bb00dac --evidence /tmp/agents/irl-shield/m3-model > /tmp/agents/irl-shield/m3-model/python-replay.log 2>&1
# Second Python call used replay_counterexamples.py, as handed back.
XDG_RUNTIME_DIR="/run/user/$(id -u)" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$(id -u)/bus" systemd-run --user --scope --slice=app-t3code-agents.slice -p CPUQuota=200% nice -n 10 env PYTHONDONTWRITEBYTECODE=1 python3 /tmp/agents/irl-shield/m3-model/replay_counterexamples.py --source WORKTREE_t3-3bb00dac --evidence /tmp/agents/irl-shield/m3-model > /tmp/agents/irl-shield/m3-model/python-replay.log 2>&1
